INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM20QEJVL', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 2, 'mcq', E'A hospital randomly assigns $90$ patients with chronic back pain to two groups. One group receives a new physical therapy regimen for $8$ weeks, while the other group continues their existing treatment. After $8$ weeks, patients in the new-regimen group report significantly lower pain scores. Which of the following is the most appropriate conclusion?', NULL, $lyceon_json$[{"key":"A","text":"The new regimen is likely to reduce pain for all back-pain patients worldwide."},{"key":"B","text":"The new regimen likely caused the reduction in pain scores among the patients in this experiment."},{"key":"C","text":"Patients who chose the new regimen were probably more motivated to recover."},{"key":"D","text":"There is an association between the regimen and pain scores, but causation cannot be determined."}]$lyceon_json$::jsonb, 'B', NULL, E'Because patients were randomly assigned to the new regimen or to the existing treatment, this is a randomized experiment. Random assignment balances pre-existing differences (such as motivation, pain severity, or fitness level) across groups, so a causal conclusion about the treatment effect is appropriate for the participants studied. The claim about all back-pain patients worldwide overgeneralizes beyond the study population. The suggestion about patients choosing the regimen contradicts the study design — random assignment means patients did not self-select, so motivation is balanced across groups. The claim that causation cannot be determined applies to observational studies, not to randomized experiments where confounders are controlled by design.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM20RA359', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 1, 'mcq', E'The function $g$ is defined by $g(x) = 3x^2 - 7$. What is the value of $g(5)$?', NULL, $lyceon_json$[{"key":"A","text":"$68$"},{"key":"B","text":"$82$"},{"key":"C","text":"$75$"},{"key":"D","text":"$38$"}]$lyceon_json$::jsonb, 'A', NULL, E'Substituting $x = 5$: $g(5) = 3(5)^2 - 7 = 3(25) - 7 = 75 - 7 = 68$. The distractor $82$ results from an arithmetic slip such as computing $3(25) + 7 = 82$ by adding instead of subtracting. The distractor $75$ comes from partial reasoning, computing $3(25) = 75$ but forgetting to subtract $7$. The distractor $38$ results from a concept gap, computing $3(5) = 15$ squared incorrectly, or applying the coefficient incorrectly as $3 \\cdot 15 - 7 = 38$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2177RTI', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 1, 'mcq', E'A rectangle has a length of $19$ and a width of $7$. What is the area of the rectangle?', NULL, $lyceon_json$[{"key":"A","text":"$26$"},{"key":"B","text":"$52$"},{"key":"C","text":"$133$"},{"key":"D","text":"$266$"}]$lyceon_json$::jsonb, 'C', NULL, E'The area of a rectangle is length times width: $A = 19 \\times 7 = 133$. The value $26$ is $19 + 7 = 26$, which adds the dimensions instead of multiplying, confusing area with part of the perimeter calculation. The value $52$ is $2(19 + 7) = 52$, which computes the perimeter instead of the area. The value $266$ is $2 \\times 19 \\times 7 = 266$, incorrectly doubling the area.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 30, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM21FGHB4', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 1, 'mcq', E'What is the $y$-intercept of the line $3x - 5y = 45$?', NULL, $lyceon_json$[{"key":"A","text":"$(0, -15)$"},{"key":"B","text":"$(0, -9)$"},{"key":"C","text":"$(0, 9)$"},{"key":"D","text":"$(15, 0)$"}]$lyceon_json$::jsonb, 'B', NULL, E'The $y$-intercept occurs where $x = 0$. Substituting into $3(0) - 5y = 45$ gives $-5y = 45$, so $y = -9$, and the intercept is $(0, -9)$. The point $(0, -15)$ results from dividing 45 by the coefficient of $x$ instead of the coefficient of $y$, a concept gap. The point $(0, 9)$ comes from a sign error, dropping the negative when dividing $45$ by $-5$. The point $(15, 0)$ is the $x$-intercept, indicating the question was misread as asking for the $x$-intercept instead of the $y$-intercept.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM21JD61X', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 3, 'grid_in', E'A rectangular box has dimensions $8$ by $6$ by $3$. A second rectangular box is similar to the first, and the longest edge of the second box is $20$. What is the volume of the second box?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '2250', ARRAY['2250'], E'The longest edge of the first box is $8$, and the corresponding edge of the second box is $20$. The scale factor is $\\frac{20}{8} = \\frac{5}{2}$. For similar solids, the volume scales by the cube of the linear scale factor. The volume of the first box is $8 \\times 6 \\times 3 = 144$. The volume of the second box is $144 \\times \\left(\\frac{5}{2}\\right)^3 = 144 \\times \\frac{125}{8} = 18 \\times 125 = 2250$. Alternatively, scale each dimension: $8 \\times \\frac{5}{2} = 20$, $6 \\times \\frac{5}{2} = 15$, $3 \\times \\frac{5}{2} = 7.5$, so volume $= 20 \\times 15 \\times 7.5 = 2250$. A common error is scaling the volume by $\\frac{5}{2}$ instead of $\\left(\\frac{5}{2}\\right)^3$, yielding $360$.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM22ANNC5', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 1, 'mcq', E'A health study finds that adults who own pets report lower stress levels than adults who do not own pets. Pet ownership was not assigned by the researchers. Which of the following is the most appropriate conclusion?', NULL, $lyceon_json$[{"key":"A","text":"Owning a pet causes adults to have lower stress levels."},{"key":"B","text":"There is an association between pet ownership and lower reported stress levels."},{"key":"C","text":"Adults without pets should adopt pets to reduce their stress."},{"key":"D","text":"The study proves that animals have a calming biological effect on humans."}]$lyceon_json$::jsonb, 'B', NULL, E'Because pet ownership was not assigned by the researchers, this is an observational study. Participants self-selected into owning or not owning pets, which introduces potential confounders (for example, people with lower stress may be more likely to adopt pets, or higher income may be associated with both pet ownership and lower stress). The study can establish an association but not causation. The causal claim that owning a pet causes lower stress is unwarranted without random assignment. The recommendation that non-owners should adopt pets is a prescriptive claim unsupported by observational evidence alone. The claim that the study proves a biological calming mechanism overgeneralizes well beyond the scope of the data.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM23ULSL0', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 1, 'mcq', E'A random sample of $350$ residents of a town found that $41\\%$ prefer expanding the public library, with a margin of error of $5\\%$. Which of the following is the best interpretation of this result?', NULL, $lyceon_json$[{"key":"A","text":"Exactly $41\\%$ of all residents prefer expanding the library."},{"key":"B","text":"It is plausible that between $36\\%$ and $46\\%$ of all residents in the town prefer expanding the library."},{"key":"C","text":"Between $36\\%$ and $46\\%$ of the residents in the sample prefer expanding the library."},{"key":"D","text":"No more than $46\\%$ of all residents could prefer expanding the library."}]$lyceon_json$::jsonb, 'B', NULL, E'A margin of error creates a confidence interval around the sample statistic ($41\\% \\pm 5\\%$), meaning it is plausible that the true population proportion falls between $36\\%$ and $46\\%$. The claim that exactly $41\\%$ of all residents prefer expanding the library treats the sample statistic as the exact population parameter, ignoring sampling variability. The claim about $36\\%$ to $46\\%$ of the sampled residents misapplies the interval — the margin of error addresses the population, not the sample, since the sample result is already known exactly. The claim of no more than $46\\%$ captures only the upper bound and ignores that the true proportion could also fall below the sample estimate.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM247ZPGC', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 2, 'mcq', E'A solution is made by mixing 5 parts acid with 23 parts water by volume. How many liters of acid are needed to make 84 liters of this solution?', NULL, $lyceon_json$[{"key":"A","text":"12"},{"key":"B","text":"15"},{"key":"C","text":"18.3"},{"key":"D","text":"23"}]$lyceon_json$::jsonb, 'B', NULL, E'The total number of parts is \\(5 + 23 = 28\\). The fraction that is acid is \\(\\frac{5}{28}\\), so the acid needed is \\(\\frac{5}{28} \\times 84 = 15\\) liters. The value 12 results from a computational slip such as dividing 84 by 7 instead of multiplying by \\(\\frac{5}{28}\\). The value 18.3 comes from dividing 84 by 23 and multiplying by 5, using the ratio \\(\\frac{5}{23}\\) instead of \\(\\frac{5}{28}\\), which neglects that 23 is only the water portion, not the total. The value 23 comes from selecting the number of water parts as the answer, confusing the given ratio component with the quantity of acid.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 70, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM24P7XNU', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 3, 'mcq', E'A political research group surveys a random sample of $800$ registered voters in a county and finds that $44\\%$ support Measure $J$ and $56\\%$ oppose it, with a margin of error of $3.5\\%$ for each estimate. A newspaper headline states: \\"County voters decisively reject Measure $J$.\\" Which of the following best evaluates the newspaper''s claim?', NULL, $lyceon_json$[{"key":"A","text":"The claim is justified because $56\\%$ is greater than $44\\%$ by $12$ percentage points."},{"key":"B","text":"The claim is justified because $800$ voters is a large enough sample to eliminate sampling error."},{"key":"C","text":"The claim is not justified because the survey did not include every registered voter."},{"key":"D","text":"The claim is justified because the confidence intervals for support ($40.5\\%$ to $47.5\\%$) and opposition ($52.5\\%$ to $59.5\\%$) do not overlap."}]$lyceon_json$::jsonb, 'D', NULL, E'The confidence interval for support is $44\\% \\pm 3.5\\%$, or $40.5\\%$ to $47.5\\%$, and for opposition it is $56\\% \\pm 3.5\\%$, or $52.5\\%$ to $59.5\\%$. Because these intervals do not overlap, the data support the conclusion that opposition exceeds support by a statistically meaningful margin, so the newspaper''s characterization is justified. The reasoning based solely on $56\\% > 44\\%$ is incomplete — it ignores whether the difference exceeds the margin of error and could hold by coincidence in a smaller-margin scenario. The claim that $800$ voters eliminates sampling error reflects a conceptual misunderstanding: no finite sample eliminates sampling error entirely. The objection that the survey did not include every voter describes an inherent feature of all sample-based surveys and does not invalidate a properly conducted poll with a margin of error.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM24Z48TL', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 3, 'grid_in', E'A ladder leans against a vertical wall. The foot of the ladder is $14$ feet from the base of the wall, and the ladder makes a $67^\\circ$ angle with the ground. What is the length of the ladder, in feet, rounded to the nearest whole number?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '36', ARRAY['36'], E'Let $L$ be the length of the ladder. The horizontal distance from the wall to the foot of the ladder is the adjacent side, and the ladder itself is the hypotenuse. Using $\\cos(67^\\circ) = \\frac{14}{L}$, we get $L = \\frac{14}{\\cos(67^\\circ)}$. Since $\\cos(67^\\circ) \\approx 0.3907$, $L \\approx \\frac{14}{0.3907} \\approx 35.83$, which rounds to $36$ feet. Common errors include using $\\sin(67^\\circ)$ instead of $\\cos(67^\\circ)$, which gives $\\frac{14}{0.9205} \\approx 15$, or computing $14 \\times \\cos(67^\\circ) \\approx 5.5$ by multiplying instead of dividing.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM25F298J', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 2, 'mcq', E'At a school, $310$ students were surveyed about their extracurricular activities. Of those surveyed, $87$ play a musical instrument, $63$ participate in debate, and $23$ do both. If a student is selected at random from those who participate in debate, what is the probability that the student also plays a musical instrument?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{23}{310}$"},{"key":"B","text":"$\\frac{23}{87}$"},{"key":"C","text":"$\\frac{63}{310}$"},{"key":"D","text":"$\\frac{23}{63}$"}]$lyceon_json$::jsonb, 'D', NULL, E'This is a conditional probability question: given that the student participates in debate, what is the probability the student also plays an instrument? The condition restricts the sample space to the $63$ debate participants. Of those, $23$ also play an instrument, so the probability is $\\frac{23}{63}$. The distractor $\\frac{23}{310}$ uses the total number of students surveyed as the denominator, computing the unconditional probability of doing both activities rather than the conditional probability. The distractor $\\frac{23}{87}$ incorrectly uses the number of instrument players as the denominator, confusing which activity defines the condition. The distractor $\\frac{63}{310}$ computes the probability of participating in debate out of all students, which is unrelated to the conditional probability asked.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM25ICX1A', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 1, 'grid_in', E'A factory produces 91 bolts every 7 minutes. At this rate, how many bolts does the factory produce in 3 minutes?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '39', ARRAY['39'], E'The production rate is \\(\\frac{91}{7} = 13\\) bolts per minute. In 3 minutes the factory produces \\(13 \\times 3 = 39\\) bolts. A common error is dividing 91 by 3 instead of first finding the unit rate, which gives approximately 30. Another error is computing \\(91 \\times 3 = 273\\) by multiplying instead of using the rate.', NULL, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2664CUP', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 2, 'mcq', E'In right triangle $MNP$ with the right angle at $P$, $\\tan(M) = \\frac{11}{60}$. What is $\\sin(M)$?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{11}{61}$"},{"key":"B","text":"$\\frac{60}{61}$"},{"key":"C","text":"$\\frac{11}{60}$"},{"key":"D","text":"$\\frac{60}{11}$"}]$lyceon_json$::jsonb, 'A', NULL, E'Since $\\tan(M) = \\frac{11}{60}$, the side opposite angle $M$ is $11$ and the side adjacent to angle $M$ is $60$. By the Pythagorean theorem, the hypotenuse is $\\sqrt{11^2 + 60^2} = \\sqrt{121 + 3600} = \\sqrt{3721} = 61$. Therefore $\\sin(M) = \\frac{\\text{opposite}}{\\text{hypotenuse}} = \\frac{11}{61}$. The value $\\frac{60}{61}$ is $\\cos(M)$, not $\\sin(M)$, confusing which trigonometric ratio was requested. The value $\\frac{11}{60}$ simply restates the given tangent value without converting to sine. The value $\\frac{60}{11}$ is the reciprocal of the tangent (i.e., $\\cot(M)$), reflecting an inverted ratio.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2728QO8', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 1, 'mcq', E'A bookstore sells a novel for \\$37. During a clearance event, the price is reduced by 30%. What is the clearance price of the novel?', NULL, $lyceon_json$[{"key":"A","text":"\\$7.00"},{"key":"B","text":"\\$11.10"},{"key":"C","text":"\\$25.90"},{"key":"D","text":"\\$33.30"}]$lyceon_json$::jsonb, 'C', NULL, E'The discount amount is \\(0.30 \\times 37 = \\$11.10\\). The clearance price is \\(37 - 11.10 = \\$25.90\\). The value \\$7.00 results from subtracting 30 from 37, treating the percentage as a dollar amount rather than computing 30% of the price. The value \\$11.10 is the discount itself, not the sale price, which means the final subtraction step was omitted. The value \\$33.30 comes from computing only a 10% discount (\\(37 \\times 0.10 = 3.70\\)) and subtracting that, applying one-third of the intended reduction.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM279FJE0', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 3, 'mcq', E'A linear function $f$ models the total cost, in dollars, of renting a bicycle for $x$ hours. If $f(5) = 85$ and $f(15) = 205$, what is the rate of change of $f$, in dollars per hour?', NULL, $lyceon_json$[{"key":"A","text":"$6$"},{"key":"B","text":"$12$"},{"key":"C","text":"$17$"},{"key":"D","text":"$25$"}]$lyceon_json$::jsonb, 'B', NULL, E'The rate of change is $\\frac{f(15) - f(5)}{15 - 5} = \\frac{205 - 85}{10} = \\frac{120}{10} = 12$ dollars per hour. The value 6 results from an arithmetic slip — dividing the cost difference by the sum of the hours instead of their difference: $\\frac{120}{20} = 6$. The value 17 comes from an equation setup error in which the student divides one function value by its input, computing $\\frac{85}{5} = 17$, which conflates total cost with the rate. The value 25 arises from misreading the question: after correctly finding the rate of change, the student solves $85 = 12(5) + b$ to get the initial value $b = 25$ and reports that instead of the rate of change.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM283E0B9', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 1, 'mcq', E'A bag contains $7$ green marbles, $4$ orange marbles, and $11$ white marbles. If one marble is selected at random, what is the probability that it is orange?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{4}{18}$"},{"key":"B","text":"$\\frac{4}{22}$"},{"key":"C","text":"$\\frac{7}{22}$"},{"key":"D","text":"$\\frac{11}{22}$"}]$lyceon_json$::jsonb, 'B', NULL, E'The total number of marbles is $7 + 4 + 11 = 22$. The probability of selecting an orange marble is $\\frac{4}{22}$, which simplifies to $\\frac{2}{11}$. The distractor $\\frac{4}{18}$ divides by $18$, which is the count of non-orange marbles ($7 + 11 = 18$) rather than the total, reflecting an equation setup error. The distractor $\\frac{7}{22}$ uses the count of green marbles instead of orange, misreading the question. The distractor $\\frac{11}{22}$ uses the count of white marbles instead of orange, also misreading the question.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM28VDZT8', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 2, 'mcq', E'Which of the following is equivalent to $\\frac{9x^2 - 49}{3x + 7}$ for $x \\neq -\\frac{7}{3}$?', NULL, $lyceon_json$[{"key":"A","text":"$3x + 7$"},{"key":"B","text":"$3x - 7$"},{"key":"C","text":"$9x - 7$"},{"key":"D","text":"$3x^2 - 7$"}]$lyceon_json$::jsonb, 'B', NULL, E'The numerator $9x^2 - 49$ is a difference of squares: $(3x)^2 - 7^2 = (3x + 7)(3x - 7)$. Dividing by $(3x + 7)$ yields $3x - 7$. The distractor $3x + 7$ results from canceling the denominator but selecting the wrong factor. The distractor $9x - 7$ comes from incorrectly factoring the numerator without recognizing that $9x^2 = (3x)^2$, treating it as $9x$ instead. The distractor $3x^2 - 7$ results from dividing each term of the numerator by $3$ instead of by the binomial $(3x + 7)$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM298MWA2', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 2, 'mcq', E'A right circular cylinder has a radius of $5$ and a height of $11$. What is the volume of the cylinder?', NULL, $lyceon_json$[{"key":"A","text":"$55\\pi$"},{"key":"B","text":"$110\\pi$"},{"key":"C","text":"$275\\pi$"},{"key":"D","text":"$550\\pi$"}]$lyceon_json$::jsonb, 'C', NULL, E'The volume of a cylinder is $V = \\pi r^2 h = \\pi(5)^2(11) = \\pi(25)(11) = 275\\pi$. The value $55\\pi$ comes from computing $\\pi r h = \\pi(5)(11)$ without squaring the radius, using the lateral surface area formula fragment instead of the volume formula. The value $110\\pi$ doubles $55\\pi$, possibly from using $2\\pi r h$, which is the lateral surface area. The value $550\\pi$ results from computing $2\\pi r^2 h = 2\\pi(25)(11)$, incorrectly doubling the volume formula.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2A4P2BA', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 3, 'mcq', E'The function $g$ is defined by $g(x) = 2(x - 3)^2 - 18$. The function $h$ is obtained by reflecting $g$ across the $x$-axis and then translating it $5$ units to the right. What is the $y$-coordinate of the vertex of $h$?', NULL, $lyceon_json$[{"key":"A","text":"$-18$"},{"key":"B","text":"$18$"},{"key":"C","text":"$-5$"},{"key":"D","text":"$36$"}]$lyceon_json$::jsonb, 'B', NULL, E'The vertex of $g$ is at $(3, -18)$. Reflecting across the $x$-axis negates the output, giving the intermediate function $-g(x) = -2(x - 3)^2 + 18$ with vertex $(3, 18)$. Translating $5$ units to the right shifts the vertex to $(8, 18)$, so the $y$-coordinate of the vertex of $h$ is $18$. The value $-18$ results from using the original vertex''s $y$-coordinate without applying the reflection. The value $-5$ comes from confusing the horizontal translation with a vertical shift. The value $36$ results from incorrectly doubling the reflected $y$-coordinate rather than simply negating the original.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2BB1ORX', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 2, 'mcq', E'A potter can spend at most $\\$403$ on materials for a batch of vases. Each vase requires $\\$13$ in clay, and there is a one-time kiln rental fee of $\\$52$. What is the maximum number of vases the potter can make?', NULL, $lyceon_json$[{"key":"A","text":"$26$"},{"key":"B","text":"$27$"},{"key":"C","text":"$31$"},{"key":"D","text":"$35$"}]$lyceon_json$::jsonb, 'B', NULL, E'The inequality is $13v + 52 \\leq 403$. Subtracting 52 from both sides gives $13v \\leq 351$, and dividing by 13 gives $v \\leq 27$. The maximum number of vases is 27. The distractor 26 results from a subtraction error such as computing $403 - 52 = 349$ and then $349 / 13 \\approx 26.8$, rounding down. The distractor 31 results from ignoring the kiln fee entirely and computing $403 / 13 = 31$. The distractor 35 results from adding the kiln fee instead of subtracting, solving $13v \\leq 403 + 52 = 455$ and obtaining $455 / 13 = 35$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2F4UP3I', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 1, 'mcq', E'A student records the number of pages she reads each day over 7 days: 34, 41, 29, 47, 38, 41, 53. What is the median number of pages read per day?', NULL, $lyceon_json$[{"key":"A","text":"38"},{"key":"B","text":"40.4"},{"key":"C","text":"41"},{"key":"D","text":"47"}]$lyceon_json$::jsonb, 'C', NULL, E'Sorting the values gives 29, 34, 38, 41, 41, 47, 53. With 7 values, the median is the 4th value, which is 41. The value 38 is the 3rd value in the sorted list, resulting from miscounting the middle position. The value 40.4 is approximately the mean \\(\\left(\\frac{283}{7} \\approx 40.4\\right)\\), reflecting confusion between the mean and the median. The value 47 is the 4th entry in the original unsorted list, which results from failing to sort the data before identifying the middle value.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 50, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2FADJN2', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 1, 'mcq', E'Which of the following expressions is equivalent to $7(2x + 9) - 3x$?', NULL, $lyceon_json$[{"key":"A","text":"$11x + 63$"},{"key":"B","text":"$11x + 9$"},{"key":"C","text":"$14x + 63$"},{"key":"D","text":"$11x - 63$"}]$lyceon_json$::jsonb, 'A', NULL, E'Distributing gives $7(2x + 9) - 3x = 14x + 63 - 3x = 11x + 63$. The distractor $11x + 9$ results from failing to distribute the $7$ to the $9$, leaving the constant as $9$ instead of $63$. The distractor $14x + 63$ omits the subtraction of $3x$ when combining like terms. The distractor $11x - 63$ applies a sign error when distributing, treating $7(9)$ as $-63$ instead of $+63$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2FBW4G8', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 2, 'mcq', E'The function $h(x) = -2(x - 4)^2 + 13$ models the height, in feet, of a ball $x$ seconds after being thrown. What is the maximum height, in feet, that the ball reaches?', NULL, $lyceon_json$[{"key":"A","text":"$4$"},{"key":"B","text":"$13$"},{"key":"C","text":"$-2$"},{"key":"D","text":"$45$"}]$lyceon_json$::jsonb, 'B', NULL, E'The function is in vertex form $h(x) = a(x - h)^2 + k$ where the vertex is at $(4, 13)$. Since the coefficient $a = -2$ is negative, the parabola opens downward, meaning the vertex represents the maximum. The maximum height is $13$ feet. The distractor $4$ results from misreading the question and selecting the $x$-coordinate of the vertex (the time at which the maximum occurs) instead of the height. The distractor $-2$ reflects a concept gap, selecting the leading coefficient rather than the vertex value. The distractor $45$ results from an equation setup error such as expanding incorrectly or substituting the wrong value of $x$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"misread_question"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2FK3MHU', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 1, 'mcq', E'A scatterplot displays data for 20 cities comparing average daily temperature in degrees Fahrenheit (\\(x\\)) to average daily electricity usage in kilowatt-hours (\\(y\\)). The correlation coefficient is \\(r = 0.83\\). Which of the following best describes the relationship shown?', NULL, $lyceon_json$[{"key":"A","text":"A strong negative linear relationship"},{"key":"B","text":"A strong positive linear relationship"},{"key":"C","text":"A weak positive linear relationship"},{"key":"D","text":"No linear relationship"}]$lyceon_json$::jsonb, 'B', NULL, E'A correlation coefficient of \\(r = 0.83\\) is positive and close to 1, indicating a strong positive linear association between temperature and electricity usage. The strong negative option misidentifies the sign of the correlation coefficient. The weak positive option underestimates the strength of the association; values of \\(r\\) above 0.7 are generally considered strong. The no-relationship option is contradicted by the magnitude of \\(r\\), which is far from 0.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 40, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2FX5BGP', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 2, 'mcq', E'The function $g(x) = -4x + b$ satisfies $g(7) = 11$. What is the value of $b$?', NULL, $lyceon_json$[{"key":"A","text":"$-39$"},{"key":"B","text":"$-17$"},{"key":"C","text":"$17$"},{"key":"D","text":"$39$"}]$lyceon_json$::jsonb, 'D', NULL, E'Substituting $x = 7$: $g(7) = -4(7) + b = -28 + b = 11$. Adding 28 to both sides gives $b = 39$. The value $-39$ arises from a sign error, computing $-(28 + 11)$ instead of $11 + 28$. The value $-17$ results from an arithmetic slip, subtracting $28$ from $11$ instead of adding: $11 - 28 = -17$. The value $17$ reflects partial reasoning — computing $28 - 11 = 17$ by reversing the subtraction direction.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2G8KEE0', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 1, 'mcq', E'A circle has a diameter of $34$. What is the radius of the circle?', NULL, $lyceon_json$[{"key":"A","text":"$11$"},{"key":"B","text":"$17$"},{"key":"C","text":"$34$"},{"key":"D","text":"$68$"}]$lyceon_json$::jsonb, 'B', NULL, E'The radius of a circle is half its diameter: $r = \\frac{34}{2} = 17$. The value $11$ results from an arithmetic error such as computing $34 / 3$ or subtracting instead of dividing. The value $34$ mistakes the diameter for the radius, not performing the required division. The value $68$ doubles the diameter instead of halving it, confusing the relationship between radius and diameter.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 30, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2H037LH', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 2, 'mcq', E'A circle in the $xy$-plane has center $(-5, 8)$ and passes through the point $(-5, 15)$. What is the equation of the circle?', NULL, $lyceon_json$[{"key":"A","text":"$(x + 5)^2 + (y - 8)^2 = 7$"},{"key":"B","text":"$(x + 5)^2 + (y - 8)^2 = 49$"},{"key":"C","text":"$(x - 5)^2 + (y + 8)^2 = 49$"},{"key":"D","text":"$(x + 5)^2 + (y - 8)^2 = 529$"}]$lyceon_json$::jsonb, 'B', NULL, E'The radius is the distance from the center $(-5, 8)$ to the point $(-5, 15)$: $r = \\sqrt{(-5 - (-5))^2 + (15 - 8)^2} = \\sqrt{0 + 49} = 7$. The standard form equation of a circle with center $(h, k)$ and radius $r$ is $(x - h)^2 + (y - k)^2 = r^2$. With $h = -5$, $k = 8$, and $r = 7$: $(x + 5)^2 + (y - 8)^2 = 49$. The equation $(x + 5)^2 + (y - 8)^2 = 7$ uses the radius instead of the radius squared, reflecting incomplete application of the formula. The equation $(x - 5)^2 + (y + 8)^2 = 49$ has the signs reversed on both center coordinates, a sign error in applying the standard form. The equation $(x + 5)^2 + (y - 8)^2 = 529$ uses $23^2 = 529$, as if the radius were $15 + 8 = 23$ instead of $15 - 8 = 7$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2HOTYEL', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 1, 'mcq', E'What value of $x$ satisfies the equation $11x + 23 = 89$?', NULL, $lyceon_json$[{"key":"A","text":"$4$"},{"key":"B","text":"$6$"},{"key":"C","text":"$8$"},{"key":"D","text":"$10$"}]$lyceon_json$::jsonb, 'B', NULL, E'Subtracting 23 from both sides gives $11x = 66$, and dividing both sides by 11 yields $x = 6$. The value 4 results from an arithmetic slip such as computing $66 \\div 11$ incorrectly. The value 8 comes from dividing 89 by 11 without first subtracting 23, an equation setup error. The value 10 arises from misreading the coefficient or the constant, for instance treating the equation as $10x + 23 = 123$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2IB589H', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 3, 'mcq', E'If $\\frac{5x^2 - 23x + 12}{5x - 3} = ax + b$ for all $x \\neq \\frac{3}{5}$, what is the value of $a + b$?', NULL, $lyceon_json$[{"key":"A","text":"$-3$"},{"key":"B","text":"$-5$"},{"key":"C","text":"$3$"},{"key":"D","text":"$5$"}]$lyceon_json$::jsonb, 'A', NULL, E'Factoring the numerator: $5x^2 - 23x + 12 = (5x - 3)(x - 4)$, verified by expanding $(5x - 3)(x - 4) = 5x^2 - 20x - 3x + 12 = 5x^2 - 23x + 12$. So $\\frac{5x^2 - 23x + 12}{5x - 3} = x - 4$, giving $a = 1$ and $b = -4$. Therefore $a + b = 1 + (-4) = -3$. The distractor $-5$ comes from a sign error such as computing $a - b = 1 - (-4) = 5$ and then negating. The distractor $3$ results from computing $b - a = -4 - 1 = -5$ and confusing it with $a - b$, or from a factoring error that yields $b = 2$. The distractor $5$ arises from computing $a - b = 1 - (-4) = 5$ instead of $a + b$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2IFSRHL', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 1, 'mcq', E'Two parallel lines are cut by a transversal. If one of the alternate interior angles measures $53^\\circ$, what is the measure, in degrees, of the other alternate interior angle?', NULL, $lyceon_json$[{"key":"A","text":"$37^\\circ$"},{"key":"B","text":"$53^\\circ$"},{"key":"C","text":"$127^\\circ$"},{"key":"D","text":"$143^\\circ$"}]$lyceon_json$::jsonb, 'B', NULL, E'Alternate interior angles formed by two parallel lines and a transversal are congruent, so the other alternate interior angle also measures $53^\\circ$. The value $37^\\circ$ comes from subtracting $90 - 53 = 37$, incorrectly treating the angle as complementary rather than congruent. The value $127^\\circ$ results from computing the supplement $180 - 53 = 127$, confusing alternate interior angles with co-interior (same-side interior) angles. The value $143^\\circ$ comes from computing $90 + 53 = 143$, an equation setup error with no geometric basis.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 30, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2IOO2IR', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 3, 'mcq', E'A retailer buys an item at wholesale for \\$84 and marks it up by 75%. During a promotion, the retailer offers a 40% discount on the marked-up price. What is the retailer''s profit or loss on the item when it is sold at the promotional price?', NULL, $lyceon_json$[{"key":"A","text":"A loss of \\$4.20"},{"key":"B","text":"A profit of \\$4.20"},{"key":"C","text":"A profit of \\$4.80"},{"key":"D","text":"A profit of \\$29.40"}]$lyceon_json$::jsonb, 'B', NULL, E'The marked-up price is \\(84 \\times 1.75 = 147\\). After a 40% discount, the selling price is \\(147 \\times 0.60 = 88.20\\). The profit is \\(88.20 - 84 = \\$4.20\\). The loss of \\$4.20 results from reversing the subtraction, computing \\(84 - 88.20\\) as negative without recognizing the selling price exceeds cost. The profit of \\$4.80 comes from an arithmetic slip in multiplying \\(147 \\times 0.60\\). The profit of \\$29.40 results from treating the net effect as \\(75\\% - 40\\% = 35\\%\\) and computing \\(84 \\times 0.35 = 29.40\\), which incorrectly subtracts percentages that apply to different bases.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 100, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2IV8DTB', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 1, 'mcq', E'Which inequality represents all values of $x$ that satisfy $9x + 17 \\leq 71$?', NULL, $lyceon_json$[{"key":"A","text":"$x \\geq 6$"},{"key":"B","text":"$x \\leq 6$"},{"key":"C","text":"$x \\leq 54$"},{"key":"D","text":"$x \\leq 9$"}]$lyceon_json$::jsonb, 'B', NULL, E'Subtracting 17 from both sides gives $9x \\leq 54$, and dividing both sides by 9 gives $x \\leq 6$. The distractor $x \\geq 6$ reverses the direction of the inequality sign. The distractor $x \\leq 54$ results from subtracting 17 but omitting the division by 9. The distractor $x \\leq 9$ results from dividing $54$ by $6$ instead of by $9$, a coefficient mix-up.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2IYB16J', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 2, 'mcq', E'What is the solution to the equation $2(3x - 5) = 4x + 18$?', NULL, $lyceon_json$[{"key":"A","text":"$4$"},{"key":"B","text":"$7$"},{"key":"C","text":"$14$"},{"key":"D","text":"$28$"}]$lyceon_json$::jsonb, 'C', NULL, E'Distributing gives $6x - 10 = 4x + 18$. Subtracting $4x$ from both sides yields $2x - 10 = 18$, and adding 10 gives $2x = 28$, so $x = 14$. The value 4 arises from a sign error: treating $-10$ as $+10$ leads to $6x + 10 = 4x + 18$, then $2x = 8$ and $x = 4$. The value 7 results from an arithmetic slip in the final division, computing $28 \\div 4$ instead of $28 \\div 2$. The value 28 comes from misreading the question and reporting the value of $2x$ rather than $x$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2JQ09IF', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 2, 'mcq', E'What is the slope of the line represented by $9x + 4y = 36$?', NULL, $lyceon_json$[{"key":"A","text":"$-\\frac{9}{4}$"},{"key":"B","text":"$-\\frac{4}{9}$"},{"key":"C","text":"$\\frac{9}{4}$"},{"key":"D","text":"$9$"}]$lyceon_json$::jsonb, 'A', NULL, E'Solving for $y$: $4y = -9x + 36$, so $y = -\\frac{9}{4}x + 9$. The slope is the coefficient of $x$, which is $-\\frac{9}{4}$. The value $-\\frac{4}{9}$ reflects a concept gap, confusing the slope with its reciprocal (swapping numerator and denominator of the coefficient ratio). The value $\\frac{9}{4}$ results from a sign error — omitting the negative sign when moving $9x$ to the other side. The value $9$ comes from partial reasoning, confusing the $y$-intercept with the slope.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2KBJGM9', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 3, 'mcq', E'A line is perpendicular to $5x - 2y = 14$ and passes through the point $(3, 1)$. What is the $y$-intercept of this line?', NULL, $lyceon_json$[{"key":"A","text":"$-7$"},{"key":"B","text":"$-\\frac{13}{2}$"},{"key":"C","text":"$-\\frac{1}{5}$"},{"key":"D","text":"$\\frac{11}{5}$"}]$lyceon_json$::jsonb, 'D', NULL, E'Rewriting $5x - 2y = 14$ in slope-intercept form gives $y = \\frac{5}{2}x - 7$, so the original slope is $\\frac{5}{2}$. A perpendicular line has slope $-\\frac{2}{5}$. Using point-slope form with $(3, 1)$: $y - 1 = -\\frac{2}{5}(x - 3)$, which gives $y = -\\frac{2}{5}x + \\frac{6}{5} + 1 = -\\frac{2}{5}x + \\frac{11}{5}$. The $y$-intercept is $\\frac{11}{5}$. The value $-7$ is the $y$-intercept of the original line, reflecting a concept gap in which the student reads the intercept without computing the perpendicular line. The value $-\\frac{13}{2}$ results from an equation setup error — using the original slope $\\frac{5}{2}$ (a parallel line) instead of the perpendicular slope, which gives $y = \\frac{5}{2}x - \\frac{13}{2}$. The value $-\\frac{1}{5}$ arises from a sign error: taking the reciprocal $\\frac{2}{5}$ without negating, which gives $y = \\frac{2}{5}x - \\frac{1}{5}$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2KTSHPW', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 3, 'mcq', E'Triangle $ABC$ is similar to triangle $DEF$. In triangle $ABC$, $AB = 13$, $BC = 21$, and $AC = 17$. If $DE = 39$, what is the perimeter of triangle $DEF$?', NULL, $lyceon_json$[{"key":"A","text":"$51$"},{"key":"B","text":"$102$"},{"key":"C","text":"$114$"},{"key":"D","text":"$153$"}]$lyceon_json$::jsonb, 'D', NULL, E'Since triangles $ABC$ and $DEF$ are similar with $AB$ corresponding to $DE$, the scale factor is $\\frac{DE}{AB} = \\frac{39}{13} = 3$. The perimeter of triangle $ABC$ is $13 + 21 + 17 = 51$. Therefore, the perimeter of triangle $DEF$ is $51 \\times 3 = 153$. The value $51$ is the perimeter of triangle $ABC$ itself, not of $DEF$, a misread of which triangle''s perimeter is requested. The value $102$ comes from doubling the perimeter of $ABC$ instead of tripling it, as if the scale factor were $2$. The value $114$ results from scaling only two of the three sides by $3$ and leaving one unchanged, computing $39 + 63 + 12 = 114$ through a partial application of the scale factor.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"misread_question"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2LQYUAN', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 3, 'mcq', E'A system of two linear equations has no solution. One of the equations is $9x - 5y = 17$. Which of the following could be the other equation?', NULL, $lyceon_json$[{"key":"A","text":"$27x - 15y = 43$"},{"key":"B","text":"$27x - 15y = 51$"},{"key":"C","text":"$9x + 5y = 17$"},{"key":"D","text":"$5x - 9y = 17$"}]$lyceon_json$::jsonb, 'A', NULL, E'A system has no solution when the lines are parallel: same slope but different $y$-intercepts. Rewriting $9x - 5y = 17$ gives slope $\\frac{9}{5}$. The equation $27x - 15y = 43$ simplifies to $9x - 5y = \\frac{43}{3}$, which has the same slope $\\frac{9}{5}$ but a different constant, so the lines are parallel and the system has no solution. The equation $27x - 15y = 51$ simplifies to $9x - 5y = 17$, which is the same line, yielding infinitely many solutions rather than none; selecting it reflects confusing no solution with dependent equations. The equation $9x + 5y = 17$ has slope $-\\frac{9}{5}$, which differs from $\\frac{9}{5}$, so the lines intersect in exactly one solution; this error reflects changing the sign of the $y$-coefficient without recognizing that it changes the slope. The equation $5x - 9y = 17$ has slope $\\frac{5}{9}$, which also differs from $\\frac{9}{5}$, producing one solution; this error reflects swapping the coefficients of $x$ and $y$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2NKKEJZ', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 2, 'mcq', E'The equation \\(y = -1.9x + 43.7\\) models the relationship between the number of days since a reservoir began draining, \\(x\\), and the depth of water in the reservoir in feet, \\(y\\). What is the best interpretation of the number 43.7 in this equation?', NULL, $lyceon_json$[{"key":"A","text":"The depth of the reservoir decreases by 43.7 feet per day."},{"key":"B","text":"The predicted depth of the reservoir at the start of draining is 43.7 feet."},{"key":"C","text":"The reservoir is predicted to be empty after 43.7 days."},{"key":"D","text":"The depth of the reservoir decreases by 1.9 feet every 43.7 days."}]$lyceon_json$::jsonb, 'B', NULL, E'In the equation \\(y = -1.9x + 43.7\\), the constant 43.7 is the y-intercept, representing the predicted value of \\(y\\) when \\(x = 0\\). Since \\(x\\) is the number of days since draining began, \\(x = 0\\) corresponds to the start of draining, so 43.7 feet is the predicted initial depth. The option describing 43.7 as a daily rate of decrease confuses the y-intercept with the slope. The option about 43.7 days conflates the y-intercept value with the x-intercept, which would be \\(\\frac{43.7}{1.9} \\approx 23\\) days. The option relating 1.9 feet to every 43.7 days misinterprets both the slope and the intercept by treating 43.7 as a time interval rather than a depth.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2P2GA4C', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 1, 'mcq', E'A function is defined by $f(x) = 7x - 13$. What is the value of $f(3)$?', NULL, $lyceon_json$[{"key":"A","text":"$-34$"},{"key":"B","text":"$-6$"},{"key":"C","text":"$8$"},{"key":"D","text":"$34$"}]$lyceon_json$::jsonb, 'C', NULL, E'Substituting $x = 3$: $f(3) = 7(3) - 13 = 21 - 13 = 8$. The value $-34$ arises from a sign error in which both terms are treated as negative, computing $-21 - 13 = -34$. The value $-6$ results from an equation setup error, computing $7 - 13 = -6$ without substituting the input into the expression. The value $34$ comes from a sign error, adding instead of subtracting: $21 + 13 = 34$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2PCY525', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 3, 'mcq', E'A researcher collected data on the age (\\(x\\), in months) and height (\\(y\\), in centimeters) of 30 saplings. She fit two models to the data:\\n\\nModel 1: \\(\\hat{y} = 3.8x + 12.4\\)\\nModel 2: \\(\\hat{y} = 0.9x^2 - 2.1x + 18.3\\)\\n\\nA sapling is 7 months old and has a height of 44 cm. Based on the residuals, which model better predicts this sapling''s height, and by how many centimeters?', NULL, $lyceon_json$[{"key":"A","text":"Model 1, by 1.3 centimeters"},{"key":"B","text":"Model 2, by 1.3 centimeters"},{"key":"C","text":"Model 2, by 3.7 centimeters"},{"key":"D","text":"Model 1, by 5.0 centimeters"}]$lyceon_json$::jsonb, 'B', NULL, E'Model 1 prediction: \\(3.8(7) + 12.4 = 26.6 + 12.4 = 39.0\\). Residual for Model 1: \\(44 - 39.0 = 5.0\\), so the absolute error is 5.0 cm. Model 2 prediction: \\(0.9(49) - 2.1(7) + 18.3 = 44.1 - 14.7 + 18.3 = 47.7\\). Residual for Model 2: \\(44 - 47.7 = -3.7\\), so the absolute error is 3.7 cm. Since 3.7 is less than 5.0, Model 2 is closer to the observed value by \\(5.0 - 3.7 = 1.3\\) cm. The option selecting Model 1 by 1.3 cm identifies the correct difference but chooses the wrong model. The option stating Model 2 by 3.7 cm reports Model 2''s residual magnitude rather than the comparison between the two models. The option stating Model 1 by 5.0 cm reports Model 1''s residual magnitude without comparing to Model 2.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 110, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2PLJLUA', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 3, 'mcq', E'On a coordinate plane, which of the following points lies in the solution region of both $5x - 3y > 14$ and $2x + 7y \\leq 29$?', NULL, $lyceon_json$[{"key":"A","text":"$(1, 5)$"},{"key":"B","text":"$(4, 2)$"},{"key":"C","text":"$(4, 1)$"},{"key":"D","text":"$(7, 3)$"}]$lyceon_json$::jsonb, 'C', NULL, E'Substituting $(4, 1)$: the first inequality gives $5(4) - 3(1) = 17 > 14$, which is true, and the second gives $2(4) + 7(1) = 15 \\leq 29$, which is also true. The point $(1, 5)$ fails the first inequality because $5(1) - 3(5) = -10$, which is not greater than 14; choosing it reflects testing only the second inequality. The point $(4, 2)$ gives $5(4) - 3(2) = 14$, which is not strictly greater than 14, so it fails at the boundary; this error reflects treating $>$ as $\\geq$. The point $(7, 3)$ satisfies the first inequality ($5(7) - 3(3) = 26 > 14$) but fails the second ($2(7) + 7(3) = 35 > 29$); choosing it reflects checking only the first inequality.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
