INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2PS2DTK', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 1, 'mcq', E'In a right triangle, the two legs have lengths $9$ and $40$. What is the length of the hypotenuse?', NULL, $lyceon_json$[{"key":"A","text":"$31$"},{"key":"B","text":"$41$"},{"key":"C","text":"$49$"},{"key":"D","text":"$81$"}]$lyceon_json$::jsonb, 'B', NULL, E'By the Pythagorean theorem, the hypotenuse $c = \\sqrt{9^2 + 40^2} = \\sqrt{81 + 1600} = \\sqrt{1681} = 41$. The value $31$ comes from subtracting $40 - 9 = 31$ instead of applying the Pythagorean theorem. The value $49$ results from adding $9 + 40 = 49$, confusing addition of legs with addition of their squares. The value $81$ comes from computing $9^2 = 81$ and stopping, reflecting a fundamental misunderstanding of the theorem.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2QA7X3N', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 3, 'mcq', E'A delivery truck travels the first 147 miles of its route at an average speed of 49 miles per hour and the remaining 140 miles at an average speed of 35 miles per hour. What is the truck''s average speed, in miles per hour, for the entire route?', NULL, $lyceon_json$[{"key":"A","text":"39"},{"key":"B","text":"41"},{"key":"C","text":"42"},{"key":"D","text":"44"}]$lyceon_json$::jsonb, 'B', NULL, E'Time for the first leg: \\(\\frac{147}{49} = 3\\) hours. Time for the second leg: \\(\\frac{140}{35} = 4\\) hours. Total distance: \\(147 + 140 = 287\\) miles. Total time: \\(3 + 4 = 7\\) hours. Average speed: \\(\\frac{287}{7} = 41\\) mph. The value 39 arises from an arithmetic slip, such as computing the total distance as 273 instead of 287. The value 42 results from taking the simple average of the two speeds, \\(\\frac{49 + 35}{2} = 42\\), which is incorrect because the truck spends different amounts of time at each speed. The value 44 comes from an error in computing the second leg''s travel time, for instance using 3.5 hours instead of 4 hours, yielding \\(\\frac{287}{6.5} \\approx 44\\).', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 100, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2R8OW4H', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 2, 'grid_in', E'If $3x^2 + 14x - 5 = 0$ and $x > 0$, what is the value of $x$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '1/3', ARRAY['1/3', '0.333', '.333'], E'Using the quadratic formula or factoring: $3x^2 + 14x - 5 = (3x - 1)(x + 5) = 0$. This gives $x = \\frac{1}{3}$ or $x = -5$. Since $x > 0$, the answer is $\\frac{1}{3}$. The factoring can be verified: $(3x - 1)(x + 5) = 3x^2 + 15x - x - 5 = 3x^2 + 14x - 5$.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2RIV3Z2', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 3, 'mcq', E'The system of equations $y = x^2 - 6x + 11$ and $y = 2x - 3$ has two solutions. What is the sum of the $x$-coordinates of these solutions?', NULL, $lyceon_json$[{"key":"A","text":"$8$"},{"key":"B","text":"$14$"},{"key":"C","text":"$4$"},{"key":"D","text":"$-8$"}]$lyceon_json$::jsonb, 'A', NULL, E'Setting the equations equal: $x^2 - 6x + 11 = 2x - 3$, which simplifies to $x^2 - 8x + 14 = 0$. By Vieta''s formulas, the sum of the roots is $\\frac{-(-8)}{1} = 8$. Alternatively, using the quadratic formula: $x = \\frac{8 \\pm \\sqrt{64 - 56}}{2} = \\frac{8 \\pm \\sqrt{8}}{2}$, and the sum of these two values is $8$. The distractor $14$ results from an equation setup error, such as using the constant term $14$ from the rearranged quadratic instead of the coefficient relationship. The distractor $4$ comes from partial reasoning, computing half the sum ($8 / 2 = 4$) or confusing the sum with a single root. The distractor $-8$ results from a sign error in applying Vieta''s formulas, using $-8$ instead of $-(-8) = 8$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2ROBOT5', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 3, 'grid_in', E'A data set consists of the values 11, 14, 17, 19, 23, 26, 31. A new data set is created by multiplying each value by 3 and then subtracting 7. What is the interquartile range of the new data set?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '36', ARRAY['36'], E'The original data sorted: 11, 14, 17, 19, 23, 26, 31. With 7 values, the median is 19 (the 4th value). The lower half is 11, 14, 17, giving \\(Q_1 = 14\\). The upper half is 23, 26, 31, giving \\(Q_3 = 26\\). The original IQR is \\(26 - 14 = 12\\). When every value is multiplied by 3, all measures of spread scale by 3, so the IQR becomes \\(12 \\times 3 = 36\\). Subtracting 7 is a constant shift that moves the center but does not affect spread, so the IQR remains 36. A common error is applying the subtraction to the IQR as well, yielding \\(36 - 7 = 29\\). Another error is computing the IQR of the original data incorrectly and then transforming that wrong value.', NULL, NULL, 'draft', 1, 100, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2S7O57H', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 1, 'mcq', E'What is the positive solution to the equation $x^2 + 5x - 36 = 0$?', NULL, $lyceon_json$[{"key":"A","text":"$9$"},{"key":"B","text":"$4$"},{"key":"C","text":"$-9$"},{"key":"D","text":"$6$"}]$lyceon_json$::jsonb, 'B', NULL, E'Factoring gives $x^2 + 5x - 36 = (x + 9)(x - 4) = 0$, so $x = -9$ or $x = 4$. The positive solution is $4$. The distractor $9$ results from a sign error when extracting the root from the factor $(x + 9)$, taking $9$ instead of $-9$. The distractor $-9$ is the negative root, which does not satisfy the condition of being positive. The distractor $6$ may result from an arithmetic error such as incorrectly factoring the quadratic as $(x + 6)(x - 6)$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2T4GQOH', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 3, 'mcq', E'What is the value of $x$ in the equation $$\\frac{3x + 1}{5} + 3 = \\frac{x + 11}{2}\\;?$$', NULL, $lyceon_json$[{"key":"A","text":"$23$"},{"key":"B","text":"$27$"},{"key":"C","text":"$50$"},{"key":"D","text":"$53$"}]$lyceon_json$::jsonb, 'A', NULL, E'Multiplying every term by 10 (the LCD of 5 and 2) gives $2(3x + 1) + 30 = 5(x + 11)$. Expanding: $6x + 2 + 30 = 5x + 55$, so $6x + 32 = 5x + 55$. Subtracting $5x$ and 32 from both sides yields $x = 23$. The value 27 arises from a sign error when distributing the 2 to the constant 1, computing $6x - 2 + 30$ instead of $6x + 2 + 30$, which gives $6x + 28 = 5x + 55$ and $x = 27$. The value 50 results from partial reasoning: failing to multiply the standalone 3 by the LCD produces $6x + 2 + 3 = 5x + 55$, yielding $x = 50$. The value 53 comes from an equation setup error in which the standalone 3 is ignored entirely, giving $6x + 2 = 5x + 55$ and $x = 53$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2U4O8GF', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 3, 'mcq', E'A box contains $13$ tokens numbered $1$ through $13$. Two tokens are drawn at random without replacement. Given that the first token drawn shows an even number, what is the probability that the second token drawn also shows an even number?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{5}{12}$"},{"key":"B","text":"$\\frac{6}{13}$"},{"key":"C","text":"$\\frac{5}{13}$"},{"key":"D","text":"$\\frac{6}{12}$"}]$lyceon_json$::jsonb, 'A', NULL, E'The even numbers from $1$ to $13$ are $2, 4, 6, 8, 10, 12$, so there are $6$ even tokens. After one even token is drawn, $5$ even tokens remain among $12$ total remaining tokens. The conditional probability is $\\frac{5}{12}$. The distractor $\\frac{6}{13}$ ignores the condition and computes the unconditional probability of drawing an even token from the full set, showing a gap in understanding dependent events. The distractor $\\frac{5}{13}$ correctly reduces the even count to $5$ but fails to reduce the total from $13$ to $12$, applying the without-replacement rule only partially. The distractor $\\frac{6}{12}$ reduces the total to $12$ but forgets to reduce the even count from $6$ to $5$, making an arithmetic slip in tracking remaining even tokens.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2VIBSC4', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 2, 'mcq', E'A university researcher conducts two independent random surveys about student satisfaction. Survey $X$ samples $150$ students and reports $67\\%$ satisfaction with a margin of error of $7\\%$. Survey $Y$ samples $900$ students and reports $64\\%$ satisfaction with a margin of error of $3\\%$. Which of the following best explains why Survey $Y$ has a smaller margin of error?', NULL, $lyceon_json$[{"key":"A","text":"Survey $Y$ reported a lower satisfaction percentage, which reduces the margin of error."},{"key":"B","text":"Survey $Y$ was more carefully designed, so its results are more reliable."},{"key":"C","text":"Survey $Y$ used a larger sample size, which decreases the margin of error."},{"key":"D","text":"Survey $Y$ surveyed students who had more consistent opinions."}]$lyceon_json$::jsonb, 'C', NULL, E'The margin of error is inversely related to the square root of the sample size. Survey $Y$ sampled $900$ students compared with Survey $X$''s $150$, which is why its margin of error ($3\\%$) is smaller than Survey $X$''s ($7\\%$). The claim that a lower satisfaction percentage reduces the margin of error conflates the value of the statistic with sampling precision — the magnitude of the estimate does not determine margin of error. The suggestion about more careful design introduces a factor not supported by the information given; the key observable difference is sample size. The claim about more consistent opinions describes variability, which can affect margin of error, but the question provides no evidence about opinion consistency — the clear difference is sample size.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"misread_question"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2WMPS2M', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 2, 'grid_in', E'A population of bacteria in a laboratory culture was 2,300 at the start of an experiment. After 4 hours, the population had increased by 35%. How many bacteria are in the culture after 4 hours?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '3105', ARRAY['3105'], E'A 35% increase means the new population is \\(1.35\\) times the original. The population after 4 hours is \\(2300 \\times 1.35 = 3105\\). A common error is reporting only the increase, \\(2300 \\times 0.35 = 805\\), rather than the total population. Another error is adding 35 to 2300, obtaining 2335, by treating the percentage as a whole number.', NULL, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2WVYRFK', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 2, 'mcq', E'In triangle $WXY$, the measure of angle $W$ is $(3k + 11)^\\circ$ and the measure of angle $X$ is $(5k - 7)^\\circ$. If the measure of angle $Y$ is $64^\\circ$, what is the value of $k$?', NULL, $lyceon_json$[{"key":"A","text":"$14$"},{"key":"B","text":"$15$"},{"key":"C","text":"$16$"},{"key":"D","text":"$22$"}]$lyceon_json$::jsonb, 'A', NULL, E'The sum of the interior angles of a triangle is $180^\\circ$. Setting up the equation: $(3k + 11) + (5k - 7) + 64 = 180$. Simplifying: $8k + 68 = 180$, so $8k = 112$ and $k = 14$. The value $15$ results from an arithmetic slip such as combining the constants incorrectly (e.g., $11 - 7 + 64 = 72$ instead of $68$). The value $16$ comes from setting the equation to $196$ or mishandling the sign on $-7$, leading to $8k + 68 = 196$ and $k = 16$. The value $22$ results from omitting angle $Y$ entirely, solving $3k + 11 + 5k - 7 = 180$ to get $8k + 4 = 180$ and $k = 22$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2XE8QNX', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 2, 'mcq', E'A data set records the number of goals scored by a soccer team in each of 13 games: 0, 0, 1, 1, 1, 2, 2, 2, 2, 3, 3, 4, 7. If the value 7 is removed from the data set, which of the following statements is true?', NULL, $lyceon_json$[{"key":"A","text":"The mean decreases and the range decreases."},{"key":"B","text":"The mean decreases and the range stays the same."},{"key":"C","text":"The median decreases and the range decreases."},{"key":"D","text":"The mean stays the same and the median decreases."}]$lyceon_json$::jsonb, 'A', NULL, E'Original data (13 values): sum is 28, mean is \\(\\frac{28}{13} \\approx 2.15\\), range is \\(7 - 0 = 7\\), and the median (7th value) is 2. After removing 7 (12 values): sum is 21, mean is \\(\\frac{21}{12} = 1.75\\), range is \\(4 - 0 = 4\\), and the median (average of 6th and 7th values) is \\(\\frac{2 + 2}{2} = 2\\). The mean decreases and the range decreases, while the median remains unchanged. The option stating the range stays the same ignores that the maximum value was removed. The option stating the median decreases incorrectly assumes that removing the largest value shifts the central position downward. The option stating the mean stays the same overlooks that removing a value well above the mean lowers the average.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 80, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2YK5RVK', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 3, 'mcq', E'Researchers investigate whether a new reading intervention improves literacy scores among elementary students. They randomly select $70$ students from schools in one rural district and randomly assign $35$ to receive the intervention and $35$ to receive standard instruction. After $12$ weeks, the intervention group has a significantly higher mean literacy score. A state education board announces: \\"This intervention is proven to raise literacy scores for all elementary students in the state.\\" Which of the following best evaluates the board''s announcement?', NULL, $lyceon_json$[{"key":"A","text":"The announcement is supported because the study used random assignment, which establishes a causal effect."},{"key":"B","text":"The announcement is not supported because the study did not use a control group."},{"key":"C","text":"The announcement overgeneralizes because the students were drawn from a single rural district, so the results may not apply to all students statewide."},{"key":"D","text":"The announcement is supported because the result was statistically significant and used a sufficient sample size."}]$lyceon_json$::jsonb, 'C', NULL, E'Although random assignment supports a causal conclusion within the study, the students were all selected from a single rural district. Factors such as demographics, school resources, and prior instructional methods may differ across the state, so the results cannot be generalized to all elementary students statewide. The board''s claim of proof for all students overgeneralizes beyond the study''s scope. The claim that random assignment alone supports the announcement addresses internal validity (causation within the study) but ignores external validity (generalizability). The assertion that the study lacked a control group contradicts the design — the $35$ students receiving standard instruction serve as the control group. The appeal to statistical significance and sample size addresses whether the observed effect is reliable within the study but does not address whether the finding extends to different populations and settings.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"misread_question"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2YZ8R5H', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 3, 'grid_in', E'A circle in the $xy$-plane has the equation $x^2 + y^2 - 14x + 6y + 33 = 0$. What is the radius of this circle?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '5', ARRAY['5'], E'To find the radius, complete the square for both $x$ and $y$ terms. Starting with $x^2 - 14x + y^2 + 6y + 33 = 0$: for $x$, take half of $-14$ to get $-7$, then square to get $49$; for $y$, take half of $6$ to get $3$, then square to get $9$. Adding these to both sides: $(x^2 - 14x + 49) + (y^2 + 6y + 9) + 33 = 49 + 9$, which simplifies to $(x - 7)^2 + (y + 3)^2 = 25$. Therefore $r^2 = 25$ and $r = 5$. A common error is forgetting to move the constant $33$ to the right side before completing the square, or computing $\\sqrt{49 + 9} = \\sqrt{58}$ without subtracting $33$.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2ZL0F7Q', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 2, 'mcq', E'A store sells notebooks for $p$ dollars each and pens for $q$ dollars each. If 5 notebooks and 3 pens cost $\\$47$, and 2 notebooks and 3 pens cost $\\$26$, what is the price, in dollars, of one notebook?', NULL, $lyceon_json$[{"key":"A","text":"$\\$3$"},{"key":"B","text":"$\\$4$"},{"key":"C","text":"$\\$7$"},{"key":"D","text":"$\\$21$"}]$lyceon_json$::jsonb, 'C', NULL, E'The system is $5p + 3q = 47$ and $2p + 3q = 26$. Subtracting the second equation from the first eliminates $q$: $3p = 21$, so $p = 7$, and one notebook costs $\\$7$. The distractor $\\$3$ results from an arithmetic error such as computing $47 - 26 = 21$ and then dividing by $7$ instead of $3$. The distractor $\\$4$ is the price of one pen ($q = 4$, found by substituting $p = 7$ into the second equation: $14 + 3q = 26$, so $3q = 12$, $q = 4$), not one notebook, reflecting a misread of what the question asks. The distractor $\\$21$ comes from stopping at $3p = 21$ without dividing by the coefficient.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"distractor","error_taxonomy":"misread_question"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW20ETJ7Q', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 2, 'mcq', E'Which choice completes the text with the most logical transition?', E'Architect Lena Vryzakis has proposed replacing the concrete stormwater channels running beneath downtown Thessaloniki with a network of subsurface bioretention cells filled with layered gravel and native root systems. Proponents note that pilot cells installed near the Rotunda in 2021 reduced peak runoff volume by 38 percent during a severe October storm. _______ the cells require manual sediment removal every fourteen months, a maintenance burden that the municipality''s current public-works staff cannot absorb without additional hiring.', $lyceon_json$[{"key":"A","text":"Furthermore,"},{"key":"B","text":"Specifically,"},{"key":"C","text":"However,"},{"key":"D","text":"For this reason,"}]$lyceon_json$::jsonb, 'C', NULL, E'The sentence before the blank presents a positive result from the pilot bioretention cells (38 percent runoff reduction), while the sentence after the blank introduces a practical drawback (manual sediment removal that exceeds current staffing capacity). "However," correctly signals this shift from a benefit to a complication. "Furthermore," would add a point in the same direction as the previous sentence, but the maintenance burden works against the optimistic pilot results. "Specifically," would elaborate on the preceding claim with a concrete instance, but the maintenance issue is a separate concern rather than a detail of the runoff reduction finding. "For this reason," implies that the maintenance burden is caused by the runoff reduction success, but sediment removal is an independent operational constraint, not a consequence of lower runoff volume.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"B":{"role":"distractor","error_taxonomy":"vocab_context_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW20GOLOW', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 2, 'mcq', E'A student is writing an introduction for a research paper and wants to establish that a widely held assumption about a historical figure is contradicted by recent archival evidence. Which choice most effectively uses information from the notes to accomplish this goal?', E'Notes:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW227ZMET', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 3, 'mcq', E'A student is writing a policy brief and wants to acknowledge the strongest objection to a proposed regulation while arguing that the regulation is still warranted. Which choice most effectively uses information from the notes to accomplish this goal?', E'Notes:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW24YQDDZ', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 1, 'mcq', E'Which choice most logically completes the text?', E'The alpine ibex (Capra ibex) typically forages at elevations between 2,400 and 3,200 meters in the European Alps. Wildlife biologist Tomasz Kowalczyk tracked 53 ibex in the Swiss canton of Valais over three summers and found that on days when midday temperatures at 2,800 meters exceeded 27 degrees Celsius, the animals ascended to elevations above 3,400 meters, where temperatures remained below 19 degrees. Because the vegetation at those higher altitudes is sparse and nutritionally poor compared to the ibex''s normal foraging zone, Kowalczyk concluded that ________', $lyceon_json$[{"key":"A","text":"the ibex prioritize thermoregulation over nutritional intake when temperatures in their usual range become uncomfortably high."},{"key":"B","text":"alpine ibex in the canton of Valais have a higher metabolic rate than ibex populations in other parts of the Alps."},{"key":"C","text":"midday temperatures at 2,800 meters in the Swiss Alps rarely exceeded 27 degrees Celsius before the year 2000."},{"key":"D","text":"the vegetation above 3,400 meters provides more calories per unit of biomass than vegetation at lower elevations."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage establishes that ibex move to higher, cooler elevations on hot days despite worse foraging conditions there. The logical conclusion is that they trade nutritional quality for thermal comfort, prioritizing thermoregulation over food intake. The option about higher metabolic rates in Valais ibex introduces a comparison the passage never makes and is unrelated to the observed behavior. The option about historical temperature thresholds introduces a claim about pre-2000 climate conditions that has no basis in the passage. The option about higher caloric content at upper elevations directly contradicts the passage, which states the vegetation there is sparse and nutritionally poor.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW266NZJV', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 2, 'mcq', E'According to the text, what primarily distinguishes the feeding strategy of Vampyroteuthis infernalis from that of other cephalopods?', E'The vampire squid (Vampyroteuthis infernalis), despite its name, does not prey on living organisms in the manner typical of its cephalopod relatives. While octopuses and other squids are active predators that capture fish, crustaceans, or mollusks, Vampyroteuthis inhabits oxygen-minimum zones at depths between 600 and 1,200 meters where dissolved oxygen levels can drop below 0.4 milliliters per liter. Marine biologist Henrique Cavalcanti documented in a 2023 study that the animal deploys two retractile filaments coated in mucus to intercept sinking particles of organic detritus — fragments of dead plankton, fecal pellets, and discarded larvacean mucus houses. Cavalcanti described this as a form of detritivory unprecedented among cephalopods, noting that the vampire squid''s metabolic rate is roughly one-tenth that of a comparably sized octopus, an adaptation consistent with an energy-poor diet.', $lyceon_json$[{"key":"A","text":"It captures sinking organic debris rather than hunting live prey, a detritivorous strategy unknown in other cephalopods."},{"key":"B","text":"It inhabits shallower waters than most cephalopods, giving it access to a wider range of food sources."},{"key":"C","text":"It uses ink-based defense mechanisms that are more sophisticated than those of other squid species."},{"key":"D","text":"It has a metabolic rate ten times higher than that of other cephalopods, requiring it to feed constantly."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage explicitly states that Cavalcanti described the vampire squid''s interception of sinking organic detritus as a form of detritivory unprecedented among cephalopods, contrasting it with the active predation practiced by octopuses and other squids. The option about capturing debris rather than hunting live prey accurately captures this distinction. The option about shallower waters contradicts the passage, which places the animal at 600 to 1,200 meters depth. The option about ink-based defense is entirely absent from the passage. The option about a metabolic rate ten times higher inverts the passage''s statement — the vampire squid''s metabolic rate is one-tenth that of a comparable octopus, not ten times greater.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"detail_misread"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2683HF5', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Neither the principal investigator nor the three postdoctoral researchers who collaborated on the longitudinal study of coral bleaching _____ confident that the sampling protocol had accounted for the unusually warm tidal patterns recorded off the Mozambican coast in late 2019.', $lyceon_json$[{"key":"A","text":"was"},{"key":"B","text":"is"},{"key":"C","text":"were"},{"key":"D","text":"has been"}]$lyceon_json$::jsonb, 'C', NULL, E'When a "neither...nor" construction joins a singular subject and a plural subject, the verb agrees with the subject closest to it. Here, "nor" is followed by "the three postdoctoral researchers," which is plural, so the verb must be plural. Additionally, the rest of the sentence uses past tense ("had accounted," "recorded"), so the past-tense plural "were" is correct. The singular past-tense "was" incorrectly agrees with the more distant subject "principal investigator" rather than the nearer "three postdoctoral researchers." The singular present-tense "is" fails on both number agreement and tense consistency. The singular present-perfect "has been" also fails on number agreement and introduces a tense inconsistent with the past-tense narrative.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW27FQ7Y1', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The playwright Desmond Okoro crafted a trilogy of one-act dramas exploring displacement and cultural memory, works that resonated with immigrant communities across three _____ and earned him a fellowship at the MacDowell artists'' residency in New Hampshire.', $lyceon_json$[{"key":"A","text":"continents,"},{"key":"B","text":"continents;"},{"key":"C","text":"continents"},{"key":"D","text":"continents—"}]$lyceon_json$::jsonb, 'C', NULL, E'The phrase "works that resonated with immigrant communities across three continents and earned him a fellowship" is a nonrestrictive appositive renaming "a trilogy of one-act dramas." Within this appositive, "resonated" and "earned" are compound verbs joined by "and." No punctuation should appear before "and" when it joins only two verb phrases rather than two independent clauses, so "continents" requires no punctuation after it. A comma after "continents" would incorrectly separate the two parts of a compound predicate. A semicolon after "continents" would signal a new independent clause, but "earned" shares its subject with "resonated" and does not begin a separate clause. An em dash after "continents" would break the compound predicate and create a grammatically incomplete structure.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"sentence_boundary_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW27GYSGH', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 1, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The collection of handwritten manuscripts that sits behind glass in the university''s archive _____ scholars from as far away as Osaka and Reykjavik each semester.', $lyceon_json$[{"key":"A","text":"draw"},{"key":"B","text":"draws"},{"key":"C","text":"have drawn"},{"key":"D","text":"are drawing"}]$lyceon_json$::jsonb, 'B', NULL, E'The subject of the sentence is "collection," which is singular. The intervening prepositional phrase "of handwritten manuscripts that sits behind glass in the university''s archive" does not change the number of the subject. The singular verb "draws" correctly agrees with "collection." The plural verb "draw" incorrectly agrees with the nearer noun "manuscripts" rather than the actual subject. The plural verb phrase "have drawn" fails to agree with the singular subject. The plural progressive form "are drawing" also fails in number agreement with the singular "collection."', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW28A2VZI', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 2, 'mcq', E'Which finding, if true, would most directly support the researchers'' hypothesis?', E'Geochemists analyzing sediment layers in Lake Toba, Sumatra, observed that strontium-to-calcium ratios in freshwater mussel shells deposited between 11,400 and 10,900 years ago fluctuated with a periodicity of approximately 37 years. The researchers hypothesized that these fluctuations correspond to cyclical shifts in monsoon intensity driven by variations in the Indian Ocean Dipole, which would have altered the volume of mineral-rich runoff entering the lake at regular intervals.', $lyceon_json$[{"key":"A","text":"Independent coral proxy records from the eastern Indian Ocean show Indian Ocean Dipole oscillations with a roughly 37-year periodicity during the same time interval."},{"key":"B","text":"Freshwater mussels in modern Lake Toba incorporate strontium into their shells at rates proportional to water temperature rather than mineral concentration."},{"key":"C","text":"Sediment cores from a lake in central Java show no detectable periodicity in strontium-to-calcium ratios during any period in the Holocene."},{"key":"D","text":"The Indian Ocean Dipole has intensified significantly over the past century due to anthropogenic climate change."}]$lyceon_json$::jsonb, 'A', NULL, E'The hypothesis links the 37-year periodicity in mussel shells to cyclical Indian Ocean Dipole variations affecting monsoon runoff. Independent coral records confirming a matching 37-year periodicity in the Indian Ocean Dipole during the same era would directly corroborate this proposed mechanism. The finding about modern mussels responding to temperature rather than mineral concentration would actually undermine the hypothesis by challenging the assumed link between mineral runoff and shell chemistry. The finding about no periodicity in Javanese lake sediments neither supports nor undermines the hypothesis, since a different lake in a different location may not share Toba''s hydrological connections. The finding about recent intensification of the Indian Ocean Dipole addresses modern trends, not the 11,400-to-10,900-year-ago interval relevant to the hypothesis.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW28TEO6Y', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 2, 'mcq', E'Which choice best describes the overall structure of the passage?', E'Economists have traditionally modeled consumer decision-making as a rational process in which individuals weigh costs and benefits before purchasing goods. This framework assumes that consumers possess complete information about available products and act to maximize personal utility. Behavioral economist Luisa Ferreira challenges this assumption by documenting what she calls "default drift" — the tendency of consumers in subscription-based markets to remain with their initial provider even when objectively cheaper alternatives are available. Ferreira''s analysis of 23,000 mobile phone contracts in Portugal showed that 68 percent of subscribers who could have saved at least fifteen euros per month by switching providers failed to do so over a four-year period.', $lyceon_json$[{"key":"A","text":"It introduces a standard economic model, then presents research that reveals a limitation of that model"},{"key":"B","text":"It defines two competing economic theories and evaluates which one better predicts consumer behavior"},{"key":"C","text":"It summarizes the history of behavioral economics and identifies its most influential finding"},{"key":"D","text":"It describes a flaw in subscription pricing and proposes a regulatory solution"}]$lyceon_json$::jsonb, 'A', NULL, E'The passage first presents the traditional rational-actor model, then introduces Ferreira''s research on default drift, which shows consumers frequently do not behave as the rational model predicts. This structure — standard model followed by complicating evidence — matches the description of introducing a model and presenting research revealing its limitation. Defining two competing theories mischaracterizes the passage; there is one established framework and one researcher''s challenge to it, not two rival theories being compared. Summarizing the history of behavioral economics overstates the passage''s scope; it discusses one specific researcher''s work, not the field''s historical development. Describing a pricing flaw and proposing a regulatory solution misreads the passage, which identifies a consumer behavior pattern but offers no policy recommendation.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW29M7IXG', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 2, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Entomologist Priya Venkatesh identified a previously unknown species of firefly in the cloud forests of central _____ her taxonomic description, published in a peer-reviewed journal, classified the insect within a genus that had not gained a new member in over thirty-seven years.', $lyceon_json$[{"key":"A","text":"Ecuador; her"},{"key":"B","text":"Ecuador, her"},{"key":"C","text":"Ecuador her"},{"key":"D","text":"Ecuador: her,"}]$lyceon_json$::jsonb, 'A', NULL, E'Two independent clauses appear on either side of the blank: one ending with "Ecuador" and the next beginning with "her taxonomic description." A semicolon correctly joins two closely related independent clauses without a coordinating conjunction. A comma alone ("Ecuador, her") produces a comma splice because no coordinating conjunction follows. Omitting punctuation entirely ("Ecuador her") creates a fused sentence. A colon followed by a misplaced comma after "her" ("Ecuador: her,") incorrectly introduces the second clause as though it were a list or explanation and inserts a comma that disrupts the subject from its appositive.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2BIVIQP', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 1, 'mcq', E'A student is writing a brief informational paragraph about a technological innovation for a school newsletter. Which choice most effectively uses information from the notes to accomplish this goal?', E'Notes:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2CQJZ40', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 3, 'mcq', E'Which choice completes the text with the most logical transition?', E'Musicologist Tomás Herrera has argued that the corrido pastorale, a narrative ballad form originating in nineteenth-century Sonoran ranching communities, influenced the harmonic structures of early Tejano conjunto music more than the polka rhythms typically credited by scholars. Several ethnomusicologists have accepted Herrera''s harmonic analysis but questioned whether the connection is causal or merely reflects shared exposure to the same European missionary hymn traditions. _______ Herrera has recently unearthed letters from two Sonoran balladeers who traveled extensively through South Texas in the 1870s, teaching their compositions to local musicians — evidence that would support direct transmission rather than parallel inheritance.', $lyceon_json$[{"key":"A","text":"Moreover,"},{"key":"B","text":"To address this objection,"},{"key":"C","text":"In any case,"},{"key":"D","text":"Granted,"}]$lyceon_json$::jsonb, 'B', NULL, E'The sentence before the blank presents a specific challenge to Herrera''s thesis: critics accept the harmonic similarity but question whether it reflects direct influence or shared ancestry. The sentence after the blank describes newly discovered letters that would demonstrate direct transmission. "To address this objection," correctly signals that Herrera''s new evidence is a targeted response to the critics'' specific challenge about causation versus parallel development. "Moreover," would simply add another point, but the letters are not a new supplementary finding; they are a strategic rebuttal aimed at the causal question. "In any case," dismisses the relevance of the preceding debate, whereas Herrera is directly engaging with the objection rather than sidestepping it. "Granted," would introduce a concession to the critics'' point, but the sentence that follows presents evidence against their alternative explanation rather than acknowledging its validity.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2CTPIZ0', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 3, 'mcq', E'Which choice best describes the function of the second sentence in the passage ("Yet Okoro''s . . . three decades")?', E'Soil scientist Priya Banerjee has demonstrated that mycorrhizal fungal networks can transfer phosphorus between plants separated by as much as nine meters in undisturbed forest soils. Yet Okoro''s 2023 replication of Banerjee''s isotope-tracing protocol in fragmented woodlands near Lagos found that phosphorus transfer declined to negligible levels when the canopy gap between donor and recipient trees exceeded 2.7 meters — a threshold routinely surpassed in forests logged within the past three decades.', $lyceon_json$[{"key":"A","text":"It provides evidence that qualifies the generalizability of the finding described in the first sentence"},{"key":"B","text":"It explains the biological mechanism underlying the process described in the first sentence"},{"key":"C","text":"It offers an example that confirms the universal applicability of Banerjee's research"},{"key":"D","text":"It shifts the passage's focus from soil science to forestry policy recommendations"}]$lyceon_json$::jsonb, 'A', NULL, E'The second sentence begins with "Yet," signaling a contrast, and presents Okoro''s finding that phosphorus transfer fails in fragmented woodlands — a condition common in logged forests. This limits the scope of Banerjee''s initial finding to undisturbed soils, qualifying its generalizability. Explaining the biological mechanism misidentifies the sentence''s function; it presents a contrasting empirical result, not an explanation of how mycorrhizal networks operate. Confirming universal applicability directly contradicts the sentence, which shows the transfer process breaks down under specific conditions. Shifting to forestry policy recommendations overstates what the sentence does; it mentions logging as a cause of canopy gaps but does not propose any policy response.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2CWGS1K', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 1, 'mcq', E'Which quotation from a music historian, if true, would most directly support the claim that Pellegrini''s compositional approach was unusual for her era?', E'Italian composer Lucia Pellegrini, active in Naples during the 1730s, wrote chamber sonatas that incorporated melodic phrases borrowed from Neapolitan folk songs — a practice considered unorthodox by the conservatory-trained composers who dominated the city''s musical establishment. While her contemporaries drew almost exclusively on formal harmonic structures derived from the works of Corelli and Scarlatti, Pellegrini wove vernacular melodies into movements otherwise built on conventional Baroque forms.', $lyceon_json$[{"key":"A","text":"\"Pellegrini's sonatas stand apart from those of her Neapolitan peers precisely because she inserted street melodies into a framework that her colleagues would have filled exclusively with learned counterpoint.\""},{"key":"B","text":"\"Naples in the 1730s was home to more active composers per capita than any other Italian city, creating intense competition for patronage.\""},{"key":"C","text":"\"Pellegrini studied at the same conservatory as several other prominent Neapolitan composers of her generation.\""},{"key":"D","text":"\"The Baroque sonata form that Pellegrini employed had been standard across Europe since the late seventeenth century.\""}]$lyceon_json$::jsonb, 'A', NULL, E'The claim is that Pellegrini''s approach was unusual for her era. The quotation about inserting street melodies where colleagues would have used only learned counterpoint directly illustrates how her method departed from prevailing practice. The quotation about the density of composers in Naples addresses the competitive environment but says nothing about her compositional distinctiveness. The quotation about attending the same conservatory as other composers implies similarity of training, not difference in approach. The quotation about the Baroque sonata form being standard describes a shared framework, which does not address what made Pellegrini''s use of that framework distinctive.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2DVXENF', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 3, 'mcq', E'Which choice completes the text with the most logical transition?', E'Epidemiologist Fatima al-Rashid has demonstrated that villages in the Thar Desert region that adopted solar-powered water purification units between 2017 and 2020 saw gastrointestinal illness rates fall by 29 percent. She attributes the improvement primarily to the elimination of the kerosene-boiling step, which villagers frequently skipped due to fuel cost, leaving water inadequately treated. Some public-health researchers have noted, however, that the same period coincided with a regional vaccination drive against rotavirus, complicating the causal attribution. _______ al-Rashid points out that control villages that received the vaccine but not the purification units showed only a 9 percent decline in gastrointestinal illness, a gap she argues is too large to attribute to the vaccine alone.', $lyceon_json$[{"key":"A","text":"Regardless,"},{"key":"B","text":"In support of this view,"},{"key":"C","text":"Acknowledging this confound,"},{"key":"D","text":"Similarly,"}]$lyceon_json$::jsonb, 'C', NULL, E'The sentence before the blank introduces a potential confounding variable (the concurrent rotavirus vaccination drive) raised by other researchers. The sentence after the blank shows al-Rashid engaging with that concern by presenting comparative data from control villages. "Acknowledging this confound," correctly signals that al-Rashid accepts the legitimacy of the methodological concern before offering evidence that her causal claim still holds. "Regardless," would dismiss the confound entirely, but al-Rashid does not ignore it; she directly addresses it with control-group data. "In support of this view," would indicate agreement with the critics'' position, but al-Rashid''s data argue against the idea that the vaccine explains the full decline. "Similarly," implies a parallel finding, but al-Rashid is responding to a challenge rather than presenting a matching observation.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2E8G15J', 'RW', 2, 'Craft and Structure', ARRAY['Cross-Text Connections'], 3, 'mcq', E'Which choice best describes how Petrov''s findings relate to Yamamoto''s hypothesis?', E'Text 1
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2EGSGKV', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 3, 'mcq', E'Which choice most logically completes the text?', E'Economist Soren Lindqvist examined municipal water pricing in 17 Swedish cities between 2008 and 2022. In cities that adopted increasing block tariffs — where the per-liter price rises as household consumption exceeds successive thresholds — average water use declined by 14 percent over the study period. However, Lindqvist found that households in the lowest income quintile reduced consumption by 23 percent, while households in the highest income quintile reduced consumption by only 6 percent. He also observed that low-income households in block-tariff cities reported significantly higher rates of skipping laundry loads and reducing bathing frequency compared to low-income households in flat-rate cities. Lindqvist argued that these findings complicate the environmental case for block tariffs because ________', $lyceon_json$[{"key":"A","text":"the conservation gains from block tariffs are achieved disproportionately through behavioral sacrifices by low-income households rather than through uniform reductions across all income groups."},{"key":"B","text":"flat-rate water pricing structures have been shown to encourage greater overall water consumption than block tariff systems in all income groups."},{"key":"C","text":"high-income households in Swedish cities are more likely than low-income households to install water-efficient appliances regardless of the pricing structure."},{"key":"D","text":"the 14 percent average reduction in water use observed across block-tariff cities is too small to produce meaningful environmental benefits."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage shows that low-income households bear a much larger share of the conservation burden (23 percent reduction with skipped laundry and reduced bathing) than high-income households (only 6 percent reduction). The logical completion is that the environmental case is complicated because the conservation gains come disproportionately from hardship-driven behavioral changes in low-income households. The option about flat-rate pricing encouraging more consumption restates the general effectiveness of block tariffs but does not explain why the environmental case is complicated — it would actually support that case. The option about high-income households installing efficient appliances introduces an unsupported claim; the passage provides no data on appliance purchases. The option characterizing 14 percent as too small misrepresents the argument; Lindqvist does not question whether the reduction is sufficient in absolute terms but rather how its burden is distributed across income groups.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2FYYLLF', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 3, 'mcq', E'As used in the passage, "arrested" most nearly means', E'The renovation of the fourteenth-century basilica had been proceeding on schedule until conservators discovered that moisture infiltration had arrested the curing process of the lime mortar applied to the nave ceiling the previous autumn. Chemical analysis revealed that the mortar had reached only forty percent of its expected compressive strength, forcing the project director to strip and reapply the entire affected section.', $lyceon_json$[{"key":"A","text":"seized by authorities"},{"key":"B","text":"halted"},{"key":"C","text":"attracted attention to"},{"key":"D","text":"accelerated"}]$lyceon_json$::jsonb, 'B', NULL, E'The passage states that moisture infiltration prevented the mortar from reaching full strength, indicating the curing process was stopped partway through. "Halted" correctly captures the sense of a process being brought to a premature stop. "Seized by authorities" refers to legal detention or confiscation, which is incoherent when applied to a chemical curing process. "Attracted attention to" means to draw notice toward something, but the passage describes the curing process being stopped, not being made conspicuous. "Accelerated" means to speed up, which directly contradicts the passage''s indication that the curing process failed to reach completion.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"vocab_context_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2H1J1KE', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 2, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'When geochemist Nadira Osman analyzed sediment cores extracted from a lakebed in northern Ethiopia, she discovered that mineral deposits near the lowest stratum _____ an isotopic signature inconsistent with regional volcanic activity during that era.', $lyceon_json$[{"key":"A","text":"exhibits"},{"key":"B","text":"exhibiting"},{"key":"C","text":"has exhibited"},{"key":"D","text":"exhibited"}]$lyceon_json$::jsonb, 'D', NULL, E'The sentence describes a past event: Nadira Osman "analyzed" and "discovered" are both in the simple past tense. The clause beginning with "that mineral deposits" requires a verb in the simple past tense to maintain consistent tense with the rest of the narrative. "Exhibited" correctly provides the past tense form. The third-person singular present "exhibits" fails to agree with the plural subject "deposits" and breaks the established past-tense frame. The present participle "exhibiting" creates a fragment because the noun clause beginning with "that mineral deposits" lacks a finite verb. The singular present perfect "has exhibited" fails to agree with the plural subject "deposits" and introduces a tense inconsistent with the narrative past.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2IO7E19', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The oversight committee insisted that the pharmaceutical company _____ all clinical trial data to an independent review panel before seeking regulatory approval for the experimental drug, a demand that delayed the company''s filing by nearly five months.', $lyceon_json$[{"key":"A","text":"discloses"},{"key":"B","text":"disclosed"},{"key":"C","text":"disclose"},{"key":"D","text":"will disclose"}]$lyceon_json$::jsonb, 'C', NULL, E'The verb "insisted" followed by "that" introduces a subjunctive clause. In Standard English, the subjunctive mood requires the base form of the verb regardless of the subject. Because "the pharmaceutical company" is the subject of this subjunctive clause, the correct form is the bare infinitive "disclose," not a conjugated form. The third-person singular present indicative "discloses" would be appropriate in a declarative statement but is incorrect in a subjunctive clause following "insisted that." The past-tense "disclosed" incorrectly shifts the clause into the indicative past. The future "will disclose" incorrectly introduces a modal auxiliary into a subjunctive construction, which requires the uninflected base form.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2J3EIOC', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 1, 'mcq', E'As used in the passage, "check" most nearly means', E'After a series of unusually warm winters, pine beetle populations surged across the boreal forests of northern Alberta. Provincial wildlife officials introduced a targeted logging program designed to check the infestation before it spread to commercially valuable spruce stands farther south.', $lyceon_json$[{"key":"A","text":"inspect"},{"key":"B","text":"restrain"},{"key":"C","text":"verify"},{"key":"D","text":"mark"}]$lyceon_json$::jsonb, 'B', NULL, E'The passage describes officials introducing a logging program to stop the beetle infestation from spreading, which means the program was intended to restrain or hold back the infestation. "Inspect" means to examine something closely, but the passage indicates active intervention against the spread, not mere observation or examination. "Verify" means to confirm the truth of something, which describes a fact-checking process unrelated to stopping a biological infestation. "Mark" means to make a visible sign on something, which has no connection to the passage''s description of controlling insect populations.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"vocab_context_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2LQL1VO', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 1, 'mcq', E'Which choice best describes the function of the passage?', E'In 2019, marine biologist Celeste Arroyo collected tissue samples from 137 hawksbill sea turtles nesting on the coast of Oaxaca, Mexico. Genetic analysis of the samples revealed that the population carried an unusually high frequency of a gene variant associated with resistance to fibropapillomatosis, a viral disease that causes debilitating tumors in sea turtles worldwide.', $lyceon_json$[{"key":"A","text":"To present a researcher's finding about a specific sea turtle population"},{"key":"B","text":"To argue that fibropapillomatosis is the primary threat to hawksbill sea turtles"},{"key":"C","text":"To compare genetic resistance across multiple species of sea turtles"},{"key":"D","text":"To explain the process by which fibropapillomatosis spreads among sea turtles"}]$lyceon_json$::jsonb, 'A', NULL, E'The passage describes Arroyo''s sample collection and the resulting genetic finding — an unusually high frequency of a disease-resistance gene variant. Its function is to present a specific research finding about one population of hawksbill turtles. Arguing that fibropapillomatosis is the primary threat goes beyond the passage, which mentions the disease but makes no claim about its ranking among threats. Comparing genetic resistance across multiple species misreads the passage, which discusses only hawksbill turtles from one location. Explaining how fibropapillomatosis spreads misidentifies the passage''s focus; the passage concerns genetic resistance in turtles, not the transmission mechanism of the virus.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2MLBGAX', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 2, 'mcq', E'Which choice most logically completes the text?', E'Cognitive psychologist Priya Ramasubramanian conducted an experiment in which 128 participants were asked to memorize a sequence of 13 unrelated words. Half the participants studied the list in a brightly lit room with white walls, while the other half studied it in a dimly lit room with dark blue walls. Both groups were tested 48 hours later in a neutral beige room with moderate lighting. The bright-room group recalled an average of 7.3 words, while the dim-room group recalled an average of 5.1 words. Ramasubramanian noted, however, that when the dim-room group was retested in a room matching their original study environment, their average recall rose to 8.4 words — surpassing the bright-room group''s performance. She proposed that ________', $lyceon_json$[{"key":"A","text":"the environmental context in which information is encoded becomes an important retrieval cue, and recall suffers when the retrieval environment differs substantially from the encoding environment."},{"key":"B","text":"dim lighting impairs the initial encoding of verbal information regardless of the conditions present during recall."},{"key":"C","text":"participants in the bright-room group would have recalled fewer words if tested in the dim room."},{"key":"D","text":"the color of a room's walls has a greater effect on memory than the level of illumination."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage shows that the dim-room group performed poorly in a mismatched neutral room but outperformed the bright-room group when retested in their original environment. This pattern directly supports the conclusion that environmental context serves as a retrieval cue, and mismatch between encoding and retrieval environments hinders recall. The option about dim lighting impairing initial encoding is contradicted by the dim-room group''s superior performance (8.4 words) when tested in matching conditions, proving encoding itself was not impaired. The option about the bright-room group recalling fewer words in the dim room is a plausible prediction but is not the broader explanatory principle the passage''s evidence calls for — Ramasubramanian is proposing a general mechanism, not a specific prediction about one group. The option about wall color mattering more than illumination isolates one variable when the passage treats the full environment (lighting and wall color together) as the contextual factor.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"detail_misread"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2OXK9LE', 'RW', 2, 'Craft and Structure', ARRAY['Cross-Text Connections'], 1, 'mcq', E'Based on the passages, how would Vasquez most likely characterize the approach Holmgren advocates?', E'Text 1
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2PN48UF', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 1, 'mcq', E'Which choice completes the text with the most logical transition?', E'Marine biologist Priya Ranganathan of the Indian Institute of Science has documented a sharp decline in seahorse populations along the southeastern coast of Tamil Nadu. Between 2018 and 2024, her team recorded a 61 percent drop in the density of Hippocampus kelloggi in surveyed tidal flats. _______ the Tamil Nadu Fisheries Department has begun restricting bottom-trawling permits in three coastal districts where the decline was steepest.', $lyceon_json$[{"key":"A","text":"Nevertheless,"},{"key":"B","text":"In other words,"},{"key":"C","text":"As a result,"},{"key":"D","text":"On the other hand,"}]$lyceon_json$::jsonb, 'C', NULL, E'The sentence before the blank describes a documented population decline, and the sentence after the blank describes a governmental action (restricting trawling permits) taken because of that decline. "As a result," correctly signals that the policy action is a consequence of the documented decline. "Nevertheless," implies that the action was taken despite an obstacle, but no obstacle is presented; the regulatory response follows logically from the findings. "In other words," introduces a restatement, but restricting permits is a new action, not a rephrasing of the decline data. "On the other hand," signals a contrasting perspective, but the regulatory action aligns with rather than opposes the research findings.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"B":{"role":"distractor","error_taxonomy":"vocab_context_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2R7NBCU', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 2, 'mcq', E'As used in the passage, "cultivated" most nearly means', E'For nearly two decades, diplomat Amara Osei cultivated relationships with officials in seven West African ministries of trade. Her sustained engagement — attending regional summits, hosting informal dinners, and mediating minor disputes before they escalated — gave her country an unusual degree of influence in shaping the bloc''s tariff negotiations.', $lyceon_json$[{"key":"A","text":"farmed"},{"key":"B","text":"refined"},{"key":"C","text":"developed deliberately"},{"key":"D","text":"harvested"}]$lyceon_json$::jsonb, 'C', NULL, E'The passage describes Osei engaging in sustained, intentional efforts over nearly twenty years — attending summits, hosting dinners, mediating disputes — to build relationships. "Developed deliberately" captures this sense of carefully nurturing connections over time through purposeful action. "Farmed" refers to growing crops or raising livestock on agricultural land, which is incoherent when applied to diplomatic relationships. "Refined" means to purify a substance or polish an already existing quality, but the passage describes building relationships from the ground up through years of effort, not polishing pre-existing ones. "Harvested" means to gather a finished crop, which implies collecting an end product rather than the long process of building that the passage emphasizes.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"vocab_context_error"},"B":{"role":"distractor","error_taxonomy":"vocab_context_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2TJFGAA', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 1, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Textile conservator Marjorie Haldane spent eleven months painstakingly restoring a fifteenth-century tapestry that had been damaged by flooding in a Bruges _____ the restored piece is now on permanent display at the Groeninge Museum.', $lyceon_json$[{"key":"A","text":"warehouse, the"},{"key":"B","text":"warehouse the"},{"key":"C","text":"warehouse. The"},{"key":"D","text":"warehouse and, the"}]$lyceon_json$::jsonb, 'C', NULL, E'The blank falls between two independent clauses: one ending with "warehouse" and the next beginning with "the restored piece is now on permanent display." A period correctly separates these two independent clauses into distinct sentences. Using a comma alone ("warehouse, the") creates a comma splice, joining two independent clauses without a coordinating conjunction. Omitting all punctuation ("warehouse the") produces a fused sentence, which is not standard. Adding "and" with a misplaced comma after it ("warehouse and, the") incorrectly separates the conjunction from the clause it introduces.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2UB3VDG', 'RW', 2, 'Craft and Structure', ARRAY['Cross-Text Connections'], 2, 'mcq', E'Which choice best describes the relationship between the two passages?', E'Text 1
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2VYCSPK', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Volcanologist Reiko Fujimura, who has monitored seismic tremors beneath Mount Ontake for over nineteen _____ argued in a recent symposium that conventional eruption-prediction models underestimate the role of shallow hydrothermal systems.', $lyceon_json$[{"key":"A","text":"years"},{"key":"B","text":"years;"},{"key":"C","text":"years,"},{"key":"D","text":"years:"}]$lyceon_json$::jsonb, 'C', NULL, E'The clause "who has monitored seismic tremors beneath Mount Ontake for over nineteen years" is a nonrestrictive relative clause modifying "Reiko Fujimura." Because this clause was opened with a comma before "who," it must be closed with a matching comma after "years" to properly set off the parenthetical information before the main verb "argued." Omitting the closing comma ("years") fails to close the nonrestrictive clause and fuses it into the main predicate. A semicolon ("years;") would incorrectly signal the start of a new independent clause, but "argued" is the main verb of the sentence, not the beginning of a separate clause. A colon ("years:") would incorrectly suggest that what follows is a list or elaboration rather than the continuation of the main clause.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"sentence_boundary_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2X5VI5J', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 3, 'mcq', E'Which choice best states the main idea of the text?', E'Urban planner Fumiko Watanabe analyzed pedestrian traffic data collected over 14 months at 23 intersections in Osaka, Japan, comparing crossings equipped with conventional countdown timers to those fitted with a new auditory pacing system that emitted rhythmic tones calibrated to the average comfortable walking speed of elderly pedestrians. At timer-equipped crossings, pedestrians over age 70 completed the crossing before the signal changed 68 percent of the time. At crossings with the auditory pacing system, the completion rate for the same demographic rose to 91 percent. Watanabe cautioned, however, that the improvement appeared to depend partly on lower ambient noise levels: at intersections where background noise exceeded 74 decibels, the auditory system''s advantage over countdown timers shrank to a statistically insignificant 4 percentage points, suggesting that the system''s efficacy may be limited to quieter urban environments.', $lyceon_json$[{"key":"A","text":"An auditory pacing system substantially improved elderly pedestrians' crossing completion rates compared to countdown timers, though the benefit diminished in high-noise environments."},{"key":"B","text":"Countdown timers are ineffective for pedestrians over age 70 and should be replaced with auditory pacing systems at all urban intersections."},{"key":"C","text":"Fumiko Watanabe's study demonstrated that ambient noise levels above 74 decibels are the primary cause of pedestrian accidents involving elderly individuals in Osaka."},{"key":"D","text":"Pedestrian traffic patterns in Osaka differ significantly from those in other Japanese cities due to the city's unique intersection design."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage presents two findings: the auditory pacing system improved elderly crossing completion rates from 68 to 91 percent, and the advantage diminished to insignificance in noisy environments above 74 decibels. The option about substantial improvement with a noise-related caveat captures both elements of the main idea. The option about replacing all countdown timers overstates the findings — the passage notes that timers still produced a 68 percent completion rate and that the auditory system failed in noisy settings, so a blanket replacement recommendation is unsupported. The option about noise causing pedestrian accidents introduces a causal claim about accidents that the passage never makes; the study measured crossing completion, not accident rates. The option about Osaka''s unique intersection design is entirely absent from the passage, which makes no comparisons to other cities.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2XKB7L7', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 3, 'mcq', E'Which finding from the study, if accurate, would most directly undermine the argument presented in the text?', E'Literary scholar Adaeze Nwosu argued in a 2023 monograph that the surge of Igbo-language novels published in southeastern Nigeria between 1958 and 1966 was driven primarily by a deliberate cultural-nationalist project coordinated through the Society of Igbo Authors, which she described as systematically commissioning and funding works intended to establish Igbo as a viable literary language independent of English. Nwosu based her argument on the Society''s surviving correspondence, which documented funding decisions for 19 of the 34 novels published during the period, and on the temporal coincidence between the Society''s founding in 1957 and the sharp increase in Igbo-language publications the following year.', $lyceon_json$[{"key":"A","text":"Fourteen of the 34 novels published between 1958 and 1966 were written by authors who had no documented affiliation with the Society of Igbo Authors and received no funding from it."},{"key":"B","text":"The Society of Igbo Authors also funded the translation of several English-language novels into Igbo during the same period."},{"key":"C","text":"Igbo-language newspaper circulation in southeastern Nigeria tripled between 1955 and 1965."},{"key":"D","text":"Several members of the Society of Igbo Authors later became prominent politicians in the Republic of Biafra."}]$lyceon_json$::jsonb, 'A', NULL, E'Nwosu''s argument attributes the novel surge to the Society''s coordinated commissioning and funding. The finding that 14 of 34 novels — over 40 percent — were by unaffiliated, unfunded authors would directly undermine the claim that the Society''s systematic project drove the surge, since a large share of the output occurred independently. The finding about the Society also funding translations does not undermine the argument; it would extend rather than weaken the scope of the Society''s cultural-nationalist activities. The finding about newspaper circulation growth is consistent with broader Igbo-language literary expansion but does not address whether the Society specifically caused the novel surge. The finding about members becoming Biafran politicians concerns their later careers and is irrelevant to whether their literary project drove novel production in the earlier period.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2ZNQ1A0', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 1, 'mcq', E'Which choice best states the main idea of the text?', E'Archaeobotanist Mirela Todorova published a 2024 study examining pollen cores extracted from lakebeds in the Rhodope Mountains of southern Bulgaria. Her analysis revealed that between 6200 and 5800 BCE, the proportion of cultivated cereal pollen in the cores increased sevenfold while wild grass pollen declined by nearly 40 percent. Todorova concluded that Neolithic farming communities in the region expanded agricultural land far more rapidly than previous models had estimated, transforming substantial portions of the mountain landscape from wild grassland to cultivated fields within just four centuries.', $lyceon_json$[{"key":"A","text":"Pollen evidence from Bulgarian lakebeds indicates that Neolithic farming transformed mountain landscapes much faster than earlier estimates suggested."},{"key":"B","text":"Archaeobotanists have determined that cereal crops were first domesticated in the Rhodope Mountains around 6200 BCE."},{"key":"C","text":"Wild grass species in the Rhodope Mountains were driven to extinction by the expansion of Neolithic agriculture."},{"key":"D","text":"Lakebeds in southern Bulgaria contain better-preserved pollen samples than those found in other parts of southeastern Europe."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage describes Todorova''s finding that pollen evidence shows Neolithic farming expanded far more rapidly than prior models predicted, transforming mountain grassland into cultivated fields in four centuries. The option about faster-than-expected transformation captures this central point. The option about first domestication in the Rhodopes overstates the evidence — the passage discusses the spread of existing cultivation, not the origin of crop domestication. The option about wild grasses being driven to extinction misrepresents the data; the passage says wild grass pollen declined by 40 percent, not that the species disappeared entirely. The option about superior pollen preservation in Bulgarian lakebeds introduces a comparative claim the passage never makes.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
